'use strict';
const fs=require('node:fs/promises'),path=require('node:path'),net=require('node:net'),crypto=require('node:crypto'),{spawn}=require('node:child_process');
const {assert,atomicJSON,readJSON,contained}=require('./core.cjs'),{Relay,decodeInvite,endpoint}=require('./friends-relay.cjs');
const GAMES=new Set(['26.3','1.21.11','1.21.1','1.20.1']);
const freePort=()=>new Promise((resolve,reject)=>{const s=net.createServer();s.once('error',reject);s.listen(0,'127.0.0.1',()=>{const port=s.address().port;s.close(()=>resolve(port));});});
function address(value){assert(typeof value==='string'&&/^[A-Za-z0-9.-]+(?::[0-9]{1,5})?$/.test(value),'Enter a server hostname and optional port.');const [host,raw]=value.split(':'),port=Number(raw||25565);assert(host.length<=253&&port>0&&port<65536,'Invalid server address.');return {host,port};}
class Multiplayer {
 constructor({data,assets,getInstance,launch,fetcher=fetch,encrypt,decrypt,emit=()=>{}}){Object.assign(this,{data,assets,getInstance,launch,fetcher,encrypt,decrypt,emit});this.root=path.join(data,'servers');this.running=new Map();this.relays=new Map();this.joins=new Map();this.book={relay:'',friends:[]};this.playit=new(require('./playit.cjs').PlayitManager)({data,assets,encrypt,decrypt,emit});}
 async init(){await fs.mkdir(this.root,{recursive:true});const saved=await readJSON(path.join(this.data,'friends.secure.json'),null);if(saved)try{this.book=this.decrypt(saved.value);}catch{}return this;}
 async save(){await atomicJSON(path.join(this.data,'friends.secure.json'),{value:this.encrypt(this.book)});}
 async config(id){assert(/^[a-f0-9-]{36}$/.test(id),'Invalid server ID.');const directory=await contained(this.root,id),config=await readJSON(path.join(directory,'server.json'),null);assert(config,'Server not found.');return {directory,config};}
 async state(){const servers=[];for(const e of await fs.readdir(this.root,{withFileTypes:true}))if(e.isDirectory()&&!e.name.startsWith('.')){const p=await readJSON(path.join(this.root,e.name,'server.json'),null);if(p)servers.push({...p,running:this.running.has(p.id),sharing:this.playit.info.running&&this.playit.info.serverId===p.id,invite:this.playit.info.address&&this.playit.info.serverId===p.id?require('./playit.cjs').friendCode({name:p.name,address:this.playit.info.address,minecraft:p.minecraft}):''});}return {servers,playit:this.playit.public(),relay:this.book.relay,friends:this.book.friends.map(f=>({id:f.id,name:f.name,minecraft:f.minecraft,kind:f.kind||'invite',address:f.address||''}))};}
 async json(url){const r=await this.fetcher(url,{signal:AbortSignal.timeout(20000),redirect:'error'});assert(r.ok,'Server metadata download failed ('+r.status+').');return r.json();}
 async create(p){assert(p.acceptEula===true,'Review and accept the Minecraft EULA before creating a server.');assert(GAMES.has(p.minecraft),'Choose one of the four supported server versions.');const name=String(p.name||'').trim();assert(name.length>0&&name.length<=60,'Enter a server name up to 60 characters.');const {instance}=await this.getInstance(p.instanceId);assert(instance.minecraft===p.minecraft&&instance.installedVersion,'Install a matching Minecraft instance first so its Java runtime is available.');const id=crypto.randomUUID(),directory=await contained(this.root,id),stage=await contained(this.root,'.create-'+id);await fs.mkdir(stage);try{const manifest=await this.json('https://piston-meta.mojang.com/mc/game/version_manifest_v2.json'),version=manifest.versions.find(v=>v.id===p.minecraft);assert(version&&/^https:\/\/piston-meta\.mojang\.com\//.test(version.url),'Official server version unavailable.');const metadata=await this.json(version.url),file=metadata.downloads?.server;assert(file&&/^https:\/\/piston-data\.mojang\.com\//.test(file.url)&&/^[a-f0-9]{40}$/.test(file.sha1)&&file.size>0&&file.size<200000000,'Invalid official server metadata.');const response=await this.fetcher(file.url,{signal:AbortSignal.timeout(180000),redirect:'error'});assert(response.ok,'Minecraft server download failed.');const chunks=[];let size=0;for await(const chunk of response.body){size+=chunk.length;assert(size<=file.size,'Server download exceeds its expected size.');chunks.push(Buffer.from(chunk));}const bytes=Buffer.concat(chunks);assert(size===file.size&&crypto.createHash('sha1').update(bytes).digest('hex')===file.sha1,'Minecraft server checksum mismatch.');await fs.writeFile(path.join(stage,'server.jar'),bytes);await fs.writeFile(path.join(stage,'eula.txt'),'# Accepted explicitly in Boralances Launcher\neula=true\n');const config={id,name,minecraft:p.minecraft,instanceId:p.instanceId,memory:Math.max(1024,Math.min(8192,Number(p.memory)||2048)),created:Date.now(),eulaAcceptedAt:Date.now(),offline:true};await atomicJSON(path.join(stage,'server.json'),config);await fs.rename(stage,directory);return config;}finally{await fs.rm(stage,{recursive:true,force:true});}}
 async start(id){assert(!this.running.has(id),'This server is already running.');const {config,directory}=await this.config(id),{instance,directory:game}=await this.getInstance(config.instanceId),java=instance.javaRelative?await contained(game,instance.javaRelative):instance.java;assert(java,'Install the matching game to prepare its Java runtime.');const gamePort=config.port||await freePort();config.port=gamePort;await atomicJSON(path.join(directory,'server.json'),config);let consolePort=await freePort();while(gamePort===consolePort)consolePort=await freePort();const token=crypto.randomBytes(32).toString('hex');await fs.writeFile(path.join(directory,'server.properties'),'server-ip=127.0.0.1\nserver-port='+gamePort+'\nonline-mode=false\nenforce-secure-profile=false\nenable-rcon=false\nenable-query=false\nmax-players=8\nview-distance=6\nsimulation-distance=4\nsync-chunk-writes=true\nspawn-protection=16\nmotd=Boralances Friends\n');await fs.copyFile(path.join(this.assets,'server/boralances-server.jar'),path.join(directory,'boralances-server.jar'));const control=path.join(directory,'control.properties');await fs.writeFile(control,'token='+token+'\nconsolePort='+consolePort+'\nserverJar='+path.join(directory,'server.jar').replaceAll('\\','/')+'\n');const child=spawn(java,['-Xms512M','-Xmx'+config.memory+'M','-Djava.awt.headless=true','-cp',path.join(directory,'boralances-server.jar'),'com.boralances.server.ServerBootstrap',control],{cwd:directory,windowsHide:true,stdio:['ignore','pipe','pipe']});const entry={child,token,consolePort,gamePort,config};this.running.set(id,entry);const log=path.join(directory,'launcher-server.log');let writes=fs.writeFile(log,'Boralances server · '+new Date().toISOString()+'\n');const output=data=>{writes=writes.then(()=>fs.appendFile(log,data)).catch(()=>{});};child.stdout.on('data',output);child.stderr.on('data',output);child.on('error',error=>this.emit('server-event',{id,error:'Could not start the Java server: '+error.code}));child.on('close',code=>{if(this.running.get(id)===entry)this.running.delete(id);this.unshare(id);this.emit('server-event',{id,closed:true,code});});return {started:true};}
 async console(id,command){const entry=this.running.get(id);assert(entry,'Start this server first.');if(command!==undefined)assert(typeof command==='string'&&command.trim()&&command.length<=1024&&!/[\r\n\0]/.test(command),'Enter one console command.');const response=await this.fetcher('http://127.0.0.1:'+entry.consolePort+(command===undefined?'/status':'/command'),{method:command===undefined?'GET':'POST',headers:{Authorization:'Bearer '+entry.token},...(command===undefined?{}:{body:command}),signal:AbortSignal.timeout(3000)}).catch(()=>null);assert(response?.ok,'Server is starting or its console is unavailable. Check its server log.');return response.json();}
 async share(id){const entry=this.running.get(id);assert(entry,'Start your server before sharing.');assert((await this.console(id)).ready,'Wait until the server is ready.');const {instance,directory}=await this.getInstance(entry.config.instanceId),java=instance.javaRelative?await contained(directory,instance.javaRelative):instance.java;const state=await this.playit.start(entry,java);if(state.address)return {invite:require('./playit.cjs').friendCode({name:entry.config.name,address:state.address,minecraft:entry.config.minecraft}),address:state.address};return {pending:true,claim:state.claim,status:state.status};}
 unshare(id){if(this.playit.info.serverId===id)this.playit.stop();this.relays.get(id)?.close();this.relays.delete(id);}

 async friend(p){if(p.remove){this.book.friends=this.book.friends.filter(f=>f.id!==p.id);await this.save();return;}assert(this.book.friends.length<100,'Maximum 100 saved friends and servers.');const name=String(p.name||'').trim();assert(name&&name.length<=60,'Enter a friend or server name.');const item=p.address?{kind:'address',address:p.address,...address(p.address),minecraft:String(p.minecraft||'1.21.1')}:(String(p.invite||'').startsWith('bora2.')?{...require('./playit.cjs').parseCode(p.invite),invite:p.invite}:{kind:'invite',...decodeInvite(p.invite),invite:p.invite});assert(GAMES.has(item.minecraft),'Choose a matching supported Minecraft version.');this.book.friends.push({...item,name,id:crypto.randomUUID()});await this.save();}
 async join(p){const friend=this.book.friends.find(f=>f.id===p.id);assert(friend,'Saved friend not found.');const {instance}=await this.getInstance(p.instanceId);assert(instance.minecraft===friend.minecraft,'Select a '+friend.minecraft+' instance before joining.');let connection;if(friend.kind==='address')connection=address(friend.address);else{const relay=new Relay();try{connection=await relay.join(friend.invite);}catch(e){relay.close();throw e;}this.joins.get(p.instanceId)?.close();this.joins.set(p.instanceId,relay);}try{return await this.launch({...p,quickJoin:connection});}catch(e){this.closeJoin(p.instanceId);throw e;}}
 closeJoin(id){this.joins.get(id)?.close();this.joins.delete(id);}
 async setRelay(value){this.book.relay=endpoint(value);await this.save();}
 async dispose(){for(const id of this.running.keys())await this.console(id,'stop').catch(()=>{});for(const id of this.relays.keys())this.unshare(id);for(const id of this.joins.keys())this.closeJoin(id);}
}
async function registerMultiplayer(ctx){const manager=await new Multiplayer(ctx).init(),{handle}=ctx;handle('multiplayer-state',()=>manager.state());handle('playit-state',()=>manager.playit.public());handle('playit-stop',()=>manager.playit.stop());handle('server-create',p=>manager.create(p));handle('server-start',p=>manager.start(p.id));handle('server-console',p=>manager.console(p.id,p.command));handle('server-stop',p=>manager.console(p.id,'stop'));handle('server-share',p=>manager.share(p.id));handle('server-unshare',p=>manager.unshare(p.id));handle('friend-save',p=>manager.friend(p));handle('friend-join',p=>manager.join(p));handle('relay-config',p=>manager.setRelay(p.endpoint));return manager;}
module.exports={Multiplayer,registerMultiplayer,address,GAMES,freePort};
